"use client";
import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FaBrain, FaTimes, FaCheckCircle, FaTimesCircle, FaRedo, FaArrowRight, FaSpinner } from 'react-icons/fa';

// A fresh, AI-written practice round for a level a child already
// finished — generated by /api/generate-task (Gemini), which pulls the
// child's recent score/wrong-answer history for this subject so the
// questions actually target what they're shaky on, instead of just
// re-serving the exact same quiz they already memorised the answers to.
export default function AiPracticeModal({ gradeId, subjectId, levelId, childId, onClose }) {
  const [status, setStatus] = useState('loading'); // loading | ready | error
  const [questions, setQuestions] = useState([]);
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState(null);
  const [typedAnswer, setTypedAnswer] = useState('');
  const [revealed, setRevealed] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [finished, setFinished] = useState(false);

  const loadRound = useCallback(async () => {
    setStatus('loading');
    setQuestions([]);
    setIndex(0);
    setSelected(null);
    setTypedAnswer('');
    setRevealed(false);
    setCorrectCount(0);
    setFinished(false);
    try {
      const res = await fetch('/api/generate-task', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          gradeId,
          subjectId,
          levelId,
          taskId: `${levelId}-ai-practice-${Date.now()}`,
          childId,
        }),
      });
      if (!res.ok) throw new Error('Generation failed');
      const data = await res.json();
      if (!data.questions?.length) throw new Error('No questions returned');
      setQuestions(data.questions);
      setStatus('ready');
    } catch (err) {
      console.error('Failed to generate AI practice round', err);
      setStatus('error');
    }
  }, [gradeId, subjectId, levelId, childId]);

  useEffect(() => { loadRound(); }, [loadRound]);

  const current = questions[index];
  const isLast = index === questions.length - 1;

  const normalize = (s) => (s || '').trim().toLowerCase();

  const submitAnswer = () => {
    if (revealed || !current) return;
    const given = current.type === 'identification' ? typedAnswer : selected;
    const isCorrect = normalize(given) === normalize(current.correctAnswer);
    if (isCorrect) setCorrectCount((c) => c + 1);
    setRevealed(true);
  };

  const next = () => {
    if (isLast) {
      setFinished(true);
      return;
    }
    setIndex((i) => i + 1);
    setSelected(null);
    setTypedAnswer('');
    setRevealed(false);
  };

  const canSubmit = current?.type === 'identification' ? typedAnswer.trim().length > 0 : selected != null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[500] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4"
      >
        <motion.div
          initial={{ opacity: 0, scale: 0.9, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20 }}
          transition={{ type: 'spring', bounce: 0.35 }}
          className="bg-white rounded-[2rem] sm:rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden relative"
        >
          <button
            onClick={onClose}
            aria-label="Close"
            className="absolute top-4 right-4 z-20 w-9 h-9 rounded-full bg-white/80 text-slate-400 hover:bg-white hover:text-slate-600 flex items-center justify-center shadow-sm transition-colors"
          >
            <FaTimes />
          </button>

          <div className="bg-gradient-to-r from-violet-500 via-indigo-500 to-blue-500 px-6 pt-7 pb-6 text-white text-center">
            <div className="w-14 h-14 mx-auto bg-white/20 rounded-2xl flex items-center justify-center text-3xl shadow-inner mb-2">
              <FaBrain />
            </div>
            <h2 className="text-xl font-black">AI Practice Round</h2>
            <p className="text-indigo-100 font-bold text-sm mt-1">A fresh set of questions, made just for you.</p>
          </div>

          <div className="p-5 sm:p-6 min-h-[16rem] flex flex-col">
            {status === 'loading' && (
              <div className="flex-1 flex flex-col items-center justify-center gap-3 py-10">
                <FaSpinner className="text-3xl text-indigo-400 animate-spin" />
                <p className="text-slate-400 font-bold text-sm">Cooking up your practice round...</p>
              </div>
            )}

            {status === 'error' && (
              <div className="flex-1 flex flex-col items-center justify-center gap-3 py-10 text-center">
                <p className="text-slate-500 font-bold text-sm">Couldn&apos;t make a practice round right now.</p>
                <button
                  onClick={loadRound}
                  className="flex items-center gap-2 px-5 py-2.5 rounded-2xl bg-indigo-500 text-white font-black text-sm hover:bg-indigo-600 transition-colors"
                >
                  <FaRedo className="text-xs" /> Try Again
                </button>
              </div>
            )}

            {status === 'ready' && !finished && current && (
              <>
                <div className="flex items-center justify-between mb-4 px-1">
                  <span className="text-xs font-black text-slate-400 uppercase tracking-wider">Practice</span>
                  <span className="text-xs font-black text-slate-400">{index + 1}/{questions.length}</span>
                </div>

                <p className="font-bold text-slate-800 text-base leading-snug mb-5">{current.questionText}</p>

                {current.type === 'identification' ? (
                  <input
                    type="text"
                    value={typedAnswer}
                    disabled={revealed}
                    onChange={(e) => setTypedAnswer(e.target.value)}
                    onKeyDown={(e) => { if (e.key === 'Enter' && canSubmit && !revealed) submitAnswer(); }}
                    placeholder="Type your answer..."
                    className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl px-5 py-3.5 font-bold text-slate-700 focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 transition-all disabled:opacity-70"
                  />
                ) : (
                  <div className="flex flex-col gap-2.5">
                    {(current.options || []).map((opt, i) => {
                      const isChosen = selected === opt;
                      const isRightOpt = revealed && normalize(opt) === normalize(current.correctAnswer);
                      const isWrongChoice = revealed && isChosen && !isRightOpt;
                      return (
                        <button
                          key={i}
                          onClick={() => !revealed && setSelected(opt)}
                          disabled={revealed}
                          className={`text-left px-4 py-3 rounded-2xl border-2 font-bold text-sm transition-colors ${isRightOpt
                            ? 'bg-emerald-50 border-emerald-300 text-emerald-700'
                            : isWrongChoice
                              ? 'bg-rose-50 border-rose-300 text-rose-600'
                              : isChosen
                                ? 'bg-indigo-50 border-indigo-400 text-indigo-700'
                                : 'bg-white border-slate-200 text-slate-700 hover:border-indigo-300'
                            }`}
                        >
                          {opt}
                        </button>
                      );
                    })}
                  </div>
                )}

                {revealed && (
                  <motion.div
                    initial={{ opacity: 0, y: -6 }}
                    animate={{ opacity: 1, y: 0 }}
                    className={`mt-4 flex items-center gap-2 px-4 py-3 rounded-2xl font-bold text-sm ${normalize(current.type === 'identification' ? typedAnswer : selected) === normalize(current.correctAnswer)
                      ? 'bg-emerald-50 text-emerald-700'
                      : 'bg-rose-50 text-rose-600'
                      }`}
                  >
                    {normalize(current.type === 'identification' ? typedAnswer : selected) === normalize(current.correctAnswer) ? (
                      <><FaCheckCircle /> Correct!</>
                    ) : (
                      <><FaTimesCircle /> The answer was: {current.correctAnswer}</>
                    )}
                  </motion.div>
                )}

                <div className="mt-6">
                  {!revealed ? (
                    <button
                      onClick={submitAnswer}
                      disabled={!canSubmit}
                      className="w-full py-3.5 rounded-2xl font-black text-white shadow-lg transition-all bg-indigo-600 hover:bg-indigo-700 disabled:opacity-40 disabled:hover:bg-indigo-600"
                    >
                      Check Answer
                    </button>
                  ) : (
                    <button
                      onClick={next}
                      className="w-full flex items-center justify-center gap-2 py-3.5 rounded-2xl font-black text-white shadow-lg bg-gradient-to-r from-emerald-500 to-teal-500 hover:shadow-xl transition-all"
                    >
                      {isLast ? 'See My Score' : 'Next Question'} <FaArrowRight className="text-xs" />
                    </button>
                  )}
                </div>
              </>
            )}

            {status === 'ready' && finished && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="flex-1 flex flex-col items-center justify-center text-center py-6"
              >
                <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center text-3xl mb-5">
                  🎉
                </div>
                <h3 className="text-2xl font-black text-slate-800 mb-1">
                  {correctCount}/{questions.length}
                </h3>
                <p className="text-slate-500 font-medium mb-6">
                  {correctCount === questions.length ? 'Perfect round — amazing work!' : 'Nice effort! Practice makes it stick.'}
                </p>
                <div className="flex items-center gap-3 w-full">
                  <button
                    onClick={loadRound}
                    className="flex-1 flex items-center justify-center gap-2 py-3 rounded-2xl bg-indigo-50 text-indigo-600 font-black text-sm hover:bg-indigo-100 transition-colors"
                  >
                    <FaRedo className="text-xs" /> Another Round
                  </button>
                  <button
                    onClick={onClose}
                    className="flex-1 py-3 rounded-2xl bg-slate-800 text-white font-black text-sm hover:bg-slate-900 transition-colors"
                  >
                    Done
                  </button>
                </div>
              </motion.div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
